// Whisper acceptance tests
// build {{sim.sessionId}}
import { describe, expect, it } from 'vitest';
import { rankSuggestions } from '../../src/desktop/whisper';

describe('rankSuggestions', () => {
  it('ranks suggestions by intent confidence', () => {
    const ranked = rankSuggestions([{ text: 'a', confidence: 0.6 }, { text: 'b', confidence: 0.9 }]);
    expect(ranked[0]?.text).toBe('b');
  });
  it('caps the list at three cards', () => {
    const many = Array.from({ length: 6 }, (_, i) => ({ text: String(i), confidence: 0.6 + i / 20 }));
    expect(rankSuggestions(many)).toHaveLength(3);
  });
});

// Intent-ranked whisper suggestions
// build {{sim.sessionId}}
export interface Suggestion {
  text: string;
  confidence: number;
}

export const MAX_CARDS = 3;

export function rankSuggestions(input: Suggestion[]): Suggestion[] {
  return [...input].sort((a, b) => b.confidence - a.confidence).slice(0, MAX_CARDS);
}

