export interface Suggestion {
  text: string;
  confidence: number;
  /** Intent the suggestion was generated for; stale when the live intent moved on. */
  intent?: string;
}

export function dropStale(cards: Suggestion[], liveIntent: string): Suggestion[] {
  return cards.filter((c) => !c.intent || c.intent === liveIntent);
}

describe('dropStale', () => {
  it('drops cards generated for another intent', () => {
    expect(dropStale([{ text: 'x', confidence: 1, intent: 'refund' }], 'billing')).toEqual([]);
  });
});

